#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    int n, maxBudget;
    std::cin >> n >> maxBudget;
    std::vector<int> numbers(n);
    int evenCount = 0, oddCount = 0;
    for (int i = 0; i < n; ++i) {
        std::cin >> numbers[i];
        if (numbers[i] % 2 == 0) {
            ++evenCount;
        } else {
            ++oddCount;
        }
    }
    if (evenCount != oddCount) {
        std::cout << 0 << std::endl;
    } else {
        std::vector<int> gapDifferences;
        int totalDiffSum = 0;
        int evenPairs = 0, oddPairs = 0;
        for (int i = 0; i < n - 1; ++i) {
            if (numbers[i] % 2 == 0) {
                ++evenPairs;
            } else {
                ++oddPairs;
            }
            if (evenPairs == oddPairs) {
                gapDifferences.push_back(std::abs(numbers[i + 1] - numbers[i]));
            }
        }
        std::sort(gapDifferences.begin(), gapDifferences.end());
        int accumulated = 0, countSelected = 0;
        for (int diff : gapDifferences) {
            if (accumulated + diff <= maxBudget) {
                accumulated += diff;
                ++countSelected;
            } else {
                break;
            }
        }
        std::cout << countSelected << std::endl;
    }
    return 0;
}
